
"use strict";
const UNIT_DATA=window.__UNIT_DATA;
let currentUnit="rio-verde";
let DADOS=UNIT_DATA[currentUnit].operational;
const WEIGHT={"Concluído":1,"Em andamento":0.5,"Não iniciado":0};
function parseUnitDate(s){const m=/^(\d{2})\/(\d{2})\/(\d{4})$/.exec(s||"");return m?new Date(+m[3],+m[2]-1,+m[1]):new Date(8640000000000000);}
let VISTORIA=parseUnitDate(DADOS.meta.vistoria);
const esc=s=>(s==null?"":String(s)).replace(/[&<>]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[m]));
const norm=s=>(s||"").normalize("NFKD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/['’]/g," ").replace(/[^a-z0-9]+/g," ").trim();
const pct=(a,b)=>b?Math.round(1000*a/b)/10:0;
function statusMeta(st){if(st==="Concluída")return{c:"s-green"};if(st==="Não iniciada")return{c:"s-red"};return{c:"s-blue"};}
function progColor(p){if(p>=100)return"var(--green)";if(p>=50)return"var(--blue)";if(p>0)return"var(--amber)";return"var(--red)";}
function sitColor(s){return s==="Concluído"?"var(--green)":s==="Em andamento"?"var(--blue)":"var(--red)";}
function parseBR(s){const m=/^(\d{2})\/(\d{2})\/(\d{4})/.exec(s||"");return m?new Date(+m[3],+m[2]-1,+m[1]):null;}
function heatColor(p){ // 0 red -> 50 amber -> 100 green
  const stops=[[0,193,59,50],[35,222,120,50],[55,222,163,58],[75,90,150,80],[100,47,143,91]];
  // simpler: piecewise hsl red->green
  const h=Math.max(0,Math.min(120,p*1.2)); return `hsl(${h},55%,42%)`;
}

function renderMast(){
  const m=DADOS.meta;
  mastLines.innerHTML=`<div>Unidade ${esc(m.unidade)}</div><div>Fases ${esc(m.fases)}</div>
    <div>Conteúdo: ${esc(m.conteudo)}</div><div>Responsável da unidade: ${esc(m.responsavel)}</div>
    <div class="upd">Data de atualização: ${esc(m.atualizacao)}</div>`;
  hcards.innerHTML=`
    <div class="hcard accent"><b>Prazo-limite do protocolo</b><div class="d">${esc(m.prazo_protocolo)}</div><small>Documentos até ${esc(m.prazo_docs)}</small></div>
    <div class="hcard"><b>Término previsto da execução</b><div class="d">${esc(m.termino)}</div><small>maior prazo entre os SCAs</small></div>
    <div class="hcard"><b>Data da vistoria</b><div class="d">${esc(m.vistoria)}</div><small>referência de criticidade</small></div>`;
  asof1.textContent="Atualizado em "+m.atualizacao; asof2.textContent="Atualizado em "+m.atualizacao; asof3.textContent="Atualizado em "+m.atualizacao;
  methodo.innerHTML=`<b style="color:var(--navy)">Metodologia:</b> progresso estimado por área a partir do checklist (Não iniciado 0% · Em andamento 50% · Concluído 100%). "Previsão inicial" = maior data da coluna Previsto da área; quando houver valor na coluna Replan, ele será apresentado como "Replanejado". A classificação Crítico/Atenção considera a margem até a vistoria (${esc(m.vistoria)}). O "Detalhamento por SCA" agrega os itens pela coluna SCA Macro e apresenta a maior previsão efetiva do grupo como "Previsão de término".`;
}

function donut(pct,size){const r=size/2-8,c=2*Math.PI*r,off=c*(1-pct/100);
  return `<svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}"><circle cx="${size/2}" cy="${size/2}" r="${r}" fill="none" stroke="#E6ECF2" stroke-width="12"/><circle cx="${size/2}" cy="${size/2}" r="${r}" fill="none" stroke="var(--navy)" stroke-width="12" stroke-linecap="round" stroke-dasharray="${c}" stroke-dashoffset="${off}" transform="rotate(-90 ${size/2} ${size/2})"/><text x="50%" y="49%" text-anchor="middle" font-size="26" font-weight="800" fill="var(--navy)">${pct}%</text><text x="50%" y="63%" text-anchor="middle" font-size="9.5" letter-spacing="1" fill="var(--muted)">CONCLUSÃO</text></svg>`;}
function renderExec(){
  execDonut.innerHTML="";
  execDonut.style.display="none";
  execLead.innerHTML="";
  execLead.style.display="none";
  const card=execDonut.closest('.exec');
  if(card)card.classList.add('exec-bars-only');
}
function renderFase(){
  const order=["1","2","Ambas","Não especificada"];
  faseBox.innerHTML=order.filter(k=>DADOS.fase[k]).map(k=>{const f=DADOS.fase[k];
    const lab=k==="Não especificada"?"Não identificada":k==="Ambas"?"Fase 1 + Fase 2":"Fase "+esc(k);
    return `<div class="phaseCell"><div class="phaseTop"><span>${lab}</span><b>${f.pct}%</b></div>
      <div class="phaseMeta">${f.conc} de ${f.total} SCAs concluídos</div>
      <div class="phaseBar"><span style="width:${Math.max(f.pct,.7)}%"></span></div></div>`;}).join('');
}
function renderReprog(){const r=DADOS.reprog;reprogVal.textContent=r.pct+"%";
  reprogSub.innerHTML=`${r.scas} de ${DADOS.totais.total_scas} SCAs · ${r.total} reprogramações registradas.`;}
function renderHeat(){
  heat.innerHTML=DADOS.macro.map(m=>`<div class="hcell" style="background:${heatColor(m.progresso)}">
    <div><div class="hm-name">${esc(m.macro)}</div><div class="hm-n">${m.n} SCAs · ${m.conc} concl. · ${m.pendentes} pend.</div></div>
    <div><div class="hm-big">${m.progresso}%</div><div class="hm-lab">progresso</div></div></div>`).join('');
  heatScale.innerHTML=[0,20,40,60,80,100].map(p=>`<span style="background:${heatColor(p)}"></span>`).join('');
}
function summaryLine(title,total,sub,conc,andamento,nao){
  const safe=total||1;
  const segment=(value,color)=>`<span style="width:${100*value/safe}%;background:${color}"></span>`;
  const stat=(value,label,color)=>`<span class="statusStat"><i style="background:${color}"></i><b>${value}</b><small>${label}</small></span>`;
  return `<div class="statusLine">
    <div class="statusTop">
      <div class="statusTitle"><strong>${total}</strong><div class="statusText"><b>${title}</b><small>${sub}</small></div></div>
      <div class="statusStats">${stat(conc,"Concluídos","var(--green)")}${stat(andamento,"Em andamento","var(--blue)")}${stat(nao,"Não iniciados","var(--red)")}</div>
    </div>
    <div class="statusTrack" aria-label="${title}: ${conc} concluídos, ${andamento} em andamento e ${nao} não iniciados">
      ${segment(conc,"var(--green)")}${segment(andamento,"var(--blue)")}${segment(nao,"var(--red)")}
    </div>
  </div>`;
}
function renderKPIs(){
  const t=DADOS.totais;
  const byIsland={};
  DADOS.areas.forEach(a=>{
    const islandKey=a.ilha&&a.ilha!=="0"?a.ilha:`Área sem agrupamento — ${a.area}`;
    (byIsland[islandKey]||(byIsland[islandKey]=[])).push(a);
  });
  const islandStatus=Object.values(byIsland).reduce((acc,list)=>{
    if(list.length&&list.every(a=>a.status==="Concluída"))acc.conc++;
    else if(list.length&&list.every(a=>a.status==="Não iniciada"))acc.nao++;
    else acc.and++;
    return acc;
  },{conc:0,and:0,nao:0});
  const islandTotal=islandStatus.conc+islandStatus.and+islandStatus.nao;
  kpiAreas.innerHTML=summaryLine("Ilhas de processo",islandTotal,"visão consolidada das áreas",islandStatus.conc,islandStatus.and,islandStatus.nao);
  kpiScas.innerHTML=summaryLine("Itens de checklist (SCAs)",t.total_scas,"base consolidada do Excel",t.itens_concluidos,t.itens_andamento,t.itens_nao_iniciados);
}
function conclList(){const done=[];DADOS.areas.forEach(a=>a.itens.forEach(i=>{if(i.situacao==="Concluído")done.push(`${esc(a.area)} — ${esc(i.item||'—')}`);}));
  return done.length?`<ul class="conclList">${done.map(d=>`<li>${d}</li>`).join('')}</ul>`:'';}
function renderDisc(){
  discBox.innerHTML=DADOS.disciplina.map(d=>{const tot=d.n||1;
    const seg=(v,c)=>v?`<span style="width:${100*v/tot}%;background:${c}"></span>`:'';
    return `<div class="discCompact">
      <div class="discTop"><span>${esc(d.disciplina)} · ${d.n}</span><b style="color:${progColor(d.progresso)}">${d.progresso}%</b></div>
      <div class="dtrack">${seg(d.conc,"var(--green)")}${seg(d.andamento,"var(--blue)")}${seg(d.nao,"var(--red)")}</div>
      <div class="discMeta">${d.conc} concl. · ${d.andamento} em and. · ${d.nao} não inic.</div>
    </div>`;}).join('')+
    `<div class="discLegend"><span class="sdot" style="background:var(--green)"></span> Concluído &nbsp; <span class="sdot" style="background:var(--blue)"></span> Em andamento &nbsp; <span class="sdot" style="background:var(--red)"></span> Não iniciado</div>`;
}
function renderGer(){
  gerBox.innerHTML=DADOS.gerente.map(g=>`<div class="manager-stat">
    <span class="manager-name">${esc(g.gerente)}</span><b>${g.pend}</b>
    <small>${g.pct}% do total de SCAs pendentes</small></div>`).join('');
}
function classify(a){const d=parseBR(a.prazo_replan||a.prazo_prev);if(!d)return"Atenção";
  const marg=(VISTORIA-d)/86400000;return marg<30?"Crítico":"Atenção";}
function classifySCA(m){const d=parseBR(m.prazo_exec);if(!d)return"Atenção";
  const marg=(VISTORIA-d)/86400000;return marg<30?"Crítico":"Atenção";}
function renderCriteria(){criteria.innerHTML=`<b>Critério de classificação</b> — pela previsão efetiva da ilha (Replanejado quando houver; caso contrário, Previsão inicial), tendo a <b>data da vistoria (${esc(DADOS.meta.vistoria)})</b> como referência: 
  <span class="k crit">Crítico</span> prazo vencido ou com menos de 30 dias de margem até a vistoria; 
  <span class="k att">Atenção</span> prazo a cumprir, com 30 dias ou mais de margem.`;}
function renderCriteriaSCA(){document.getElementById("criteriaSCA").innerHTML=`<b>Critério de classificação</b> — pela <b>Previsão de término</b> do SCA, tendo a <b>data da vistoria (${esc(DADOS.meta.vistoria)})</b> como referência: 
  <span class="k crit">Crítico</span> previsão posterior à vistoria ou com menos de 30 dias de margem; 
  <span class="k att">Atenção</span> previsão com 30 dias ou mais de margem até a vistoria.`;}
function renderAttention(){
  const list=DADOS.areas.filter(a=>a.status!=="Concluída").map(a=>({...a,cls:classify(a)}))
    .sort((x,y)=>((x.cls==="Crítico"?0:1)-(y.cls==="Crítico"?0:1))||(y.n_itens-x.n_itens));
  attention.innerHTML=list.map(a=>{
    const items=a.itens.map(i=>`<li><span class="sdot" style="background:${sitColor(i.situacao)}"></span><span>${esc(i.item||'—')}</span></li>`).join('');
    return `<div class="att ${a.cls==='Crítico'?'crit':''}"><div class="tag">${a.cls}</div>
      <h4>${esc(a.area)}</h4><div class="m">${a.n_itens} SCAs · prazo ${esc(a.prazo_prev)}</div>
      <ul>${items}</ul></div>`;}).join('');
}
let sortK="n",sortDir=-1,macroFilterReady=false;
function renderTable(){
  const sel=document.getElementById('fMacro');
  if(!macroFilterReady){sel.innerHTML='<option value="">Todos os SCA</option>'+DADOS.sca_macro.map(m=>`<option>${esc(m.macro)}</option>`).join('');macroFilterReady=true;}
  const q=norm(document.getElementById('q').value),fs=document.getElementById('fStatus').value,fm=sel.value;
  let rows=DADOS.sca_macro.filter(m=>(!q||norm(m.macro).includes(q))&&(!fs||m.status===fs)&&(!fm||m.macro===fm));
  const ord={"Não iniciada":0,"Em andamento":1,"Concluída":2};
  rows=[...rows].sort((x,y)=>{let A,B;if(sortK==="status"){A=ord[x.status];B=ord[y.status];}else if(sortK==="criticidade"){A=classifySCA(x)==="Crítico"?0:1;B=classifySCA(y)==="Crítico"?0:1;}else if(sortK==="macro"){A=norm(x.macro);B=norm(y.macro);}else if(sortK==="prazo_exec"){A=parseBR(x.prazo_exec)||0;B=parseBR(y.prazo_exec)||0;}else{A=x[sortK];B=y[sortK];}return A<B?-sortDir:A>B?sortDir:0;});
  document.querySelector('#tbl tbody').innerHTML=rows.map(m=>{const s=statusMeta(m.status),crit=classifySCA(m);
    return `<tr><td><div class="areaName">${esc(m.macro)}</div><div class="areaCod">${m.conc} concl. · ${m.andamento} em and. · ${m.nao} não inic.</div></td>
      <td><span class="chip ${s.c}">${m.status}</span></td>
      <td><div class="pcell"><div class="pbar"><span style="width:${m.progresso}%;background:${progColor(m.progresso)}"></span></div><b class="mono">${m.progresso}%</b></div></td>
      <td class="mono">${m.n}</td>
      <td class="mono">${m.areas}</td><td class="mono">${esc(m.prazo_exec)}</td>
      <td><span class="chip ${crit==='Crítico'?'s-red':'s-amber'}">${crit}</span></td></tr>`;}).join('');
  document.getElementById('tblCount').textContent=`${rows.length} de ${DADOS.sca_macro.length} SCA`;
  document.querySelectorAll('#tbl thead th').forEach(th=>{th.classList.remove('asc','desc');if(th.dataset.k===sortK)th.classList.add(sortDir>0?'asc':'desc');});
}

/* detail */
let detFilter="all",selIlha="",selDisc="",selSup="",selGer="",selCrit="";
function renderDetFilters(){
  const f=[["all","Todas"],["Não iniciada","Não iniciadas"],["Em andamento","Em andamento"],["com","Com fotos"]];
  detFilters.innerHTML=f.map(([k,l])=>`<button class="pill ${k===detFilter?'active':''}" data-f="${k}">${l}</button>`).join('');
  detFilters.querySelectorAll('.pill').forEach(b=>b.onclick=()=>{detFilter=b.dataset.f;renderDetFilters();renderDetail();});
  const uniq=(f)=>[...new Set(DADOS.areas.flatMap(a=>f(a)).filter(Boolean))].sort();
  const ilhas=uniq(a=>[a.ilha&&a.ilha!=='0'?a.ilha:null]);
  const discs=uniq(a=>a.itens.map(i=>i.disciplina));
  const sups=uniq(a=>a.itens.map(i=>i.supervisor));
  const gers=uniq(a=>a.itens.map(i=>i.gerente));
  const mk=(id,lab,opts,val)=>`<select data-sel="${id}"><option value="">${lab}: todos</option>${opts.map(o=>`<option ${o===val?'selected':''}>${esc(o)}</option>`).join('')}</select>`;
  detSelbar.innerHTML=mk("ilha","Ilha de processo",ilhas,selIlha)+mk("disc","Disciplina",discs,selDisc)+mk("sup","Supervisor responsável",sups,selSup)+mk("ger","Gerente responsável",gers,selGer)+mk("crit","Criticidade",["Crítico","Atenção"],selCrit);
  detSelbar.querySelectorAll('select').forEach(s=>s.onchange=()=>{const k=s.dataset.sel;if(k==="ilha")selIlha=s.value;if(k==="disc")selDisc=s.value;if(k==="sup")selSup=s.value;if(k==="ger")selGer=s.value;if(k==="crit")selCrit=s.value;renderDetail();});
}
function renderDetail(){
  const ord={"Não iniciada":0,"Em andamento":1,"Concluída":2};
  let areas=[...DADOS.areas].sort((x,y)=>(ord[x.status]-ord[y.status])||(x.progresso-y.progresso)||norm(x.area).localeCompare(norm(y.area)));
  if(detFilter==="com")areas=areas.filter(a=>(a.projeto&&a.projeto.length)||(a.campo&&a.campo.length));
  else if(detFilter!=="all")areas=areas.filter(a=>a.status===detFilter);
  if(selIlha)areas=areas.filter(a=>a.ilha===selIlha);
  if(selDisc)areas=areas.filter(a=>a.itens.some(i=>i.disciplina===selDisc));
  if(selSup)areas=areas.filter(a=>a.itens.some(i=>i.supervisor===selSup));
  if(selGer)areas=areas.filter(a=>a.itens.some(i=>i.gerente===selGer));
  if(selCrit)areas=areas.filter(a=>classify(a)===selCrit);
  const img=(src,cap)=>`<img loading="lazy" src="${src}" data-cap="${esc(cap)}">`;
  document.getElementById('detail').innerHTML=areas.map(a=>{
    const s=statusMeta(a.status),pend=a.n_itens-a.concluidos,crit=classify(a);
    const scas=a.itens.map(i=>`<div class="scaline"><div class="sca-main"><div class="sca-name">${esc(i.item||'—')}</div>
        <div class="sca-meta">${esc(i.disciplina||'—')} · Supervisor: ${esc(i.supervisor||'Não informado')}</div></div>
        <span class="sdot" style="background:${sitColor(i.situacao)}" title="${esc(i.situacao)}"></span></div>`).join('');
    const proj=(a.projeto||[]),campo=(a.campo||[]);
    let gal="";
    if(proj.length||campo.length){gal=`<div class="ac-gallery">
      ${proj.length?`<div class="galrow"><div class="gallab">PROJETO</div><div class="galimgs">${proj.map((s2,i)=>img(s2,a.area+' — projeto '+(i+1))).join('')}</div></div>`:''}
      ${campo.length?`<div class="galrow"><div class="gallab campo">CAMPO</div><div class="galimgs">${campo.map((s2,i)=>img(s2,a.area+' — campo '+(i+1))).join('')}</div></div>`:''}</div>`;
    }else gal=`<div class="nogal">🖼️ Sem registro fotográfico nesta atualização</div>`;
    const pptNote=a.pend_ppt&&a.pend_ppt.length?`<h5>Nota de campo</h5><div style="font-size:11.5px;line-height:1.35;color:#42505e">${esc(a.pend_ppt.join(' · '))}</div>`:'';
    return `<div class="area-card"><div class="ac-head ${crit==='Crítico'?'crit-bg':'att-bg'}"><div class="tt"><h3>${esc(a.area)}</h3>
        <div class="cod">Cód. ${esc(a.cod)}${a.fase?' · Fase '+esc(a.fase):''} · Previsão inicial ${esc(a.prazo_prev)}${a.prazo_replan?' · Replanejado '+esc(a.prazo_replan):''}</div></div>
        <span class="crit-tag ${crit==='Crítico'?'crit':'att'}">${crit}</span>
        <span class="chip ${s.c}">${a.status}</span>
        <div class="prg"><div class="num" style="color:${progColor(a.progresso)}">${a.progresso}%</div><div class="lab">Progresso</div></div></div>
      <div class="ac-body"><div class="ac-info">
        <div class="row"><span>SCAs</span><b>${a.n_itens} <span style="color:var(--muted);font-weight:500">(${pct(a.n_itens,DADOS.totais.total_scas)}% do total)</span></b></div>
        <div class="row"><span>Pendentes</span><b style="color:${pend?'var(--red)':'var(--green)'}">${pend} <span style="color:var(--muted);font-weight:500">(${pct(pend,a.n_itens)}%)</span></b></div>
        <div class="row"><span>Concluídos</span><b style="color:var(--green)">${a.concluidos} <span style="color:var(--muted);font-weight:500">(${pct(a.concluidos,a.n_itens)}%)</span></b></div>
        <h5>SCAs</h5>${scas}${pptNote}
      </div>${gal}</div></div>`;}).join('') || `<div class="nogal" style="background:#fff;border:1px solid var(--line);border-radius:14px">Nenhuma área para os filtros selecionados.</div>`;
  bindLightbox();
}
function bindLightbox(){document.querySelectorAll('.galimgs img').forEach(im=>im.onclick=()=>{lbImg.src=im.src;lbCap.textContent=im.dataset.cap||'';lightbox.classList.add('on');});}
lightbox.onclick=()=>lightbox.classList.remove('on');



