const ORIGINAL_DOCUMENT_TITLE=document.title;
let plantPinned=false;
function plantZoneColor(a){return a.status==="Concluída"?"var(--green)":a.status==="Não iniciada"?"var(--red)":"var(--blue)";}
function plantIslandAreas(island){return DADOS.areas.filter(a=>PLANT_REF[a.area]&&PLANT_REF[a.area].island===island);}
function plantLatestDate(areas){
  const ds=areas.map(a=>parseBR(a.prazo_prev)).filter(Boolean).sort((a,b)=>b-a);
  if(!ds.length)return"—";
  return String(ds[0].getDate()).padStart(2,"0")+"/"+String(ds[0].getMonth()+1).padStart(2,"0")+"/"+ds[0].getFullYear();
}
function plantIslandClass(areas){
  if(areas.length&&areas.every(a=>a.status==="Concluída"))return"Concluído";
  return areas.some(a=>classify(a)==="Crítico")?"Crítico":"Atenção";
}
function plantTooltipHTML(area){
  const ref=PLANT_REF[area.area],members=plantIslandAreas(ref.island),cls=plantIslandClass(members);
  const n=members.reduce((s,a)=>s+a.n_itens,0),latest=plantLatestDate(members);
  const groups=members.map(a=>`<div class="map-group"><div class="map-group-title"><span>${esc(a.area)}</span><span>${a.n_itens} SCA${a.n_itens===1?'':'s'}</span></div><ul>${a.itens.map(i=>`<li><span class="sdot" style="background:${sitColor(i.situacao)}"></span><span>${esc(i.item||'—')}</span></li>`).join('')}</ul></div>`).join('');
  return {cls,html:`<div class="tag">${cls}</div><h4>${esc(ref.island)}</h4><div class="m">Ilha ${esc(ref.islandCode)} · ${members.length} área${members.length===1?'':'s'} · ${n} SCAs · prazo ${esc(latest)}</div><div class="map-area-ref"><b>Área destacada:</b> ${esc(area.area)} · <b>Código:</b> ${esc(ref.code)}</div>${groups}`};
}
function plantTooltipStatic(zone){
  const area=zone.dataset.area||"Área",meta=PLANT_AREA_META[area]||{},code=zone.dataset.code||"—";
  return {cls:"Sem dados",html:`<div class="tag">Sem dados</div><h4>${esc(area)}</h4><div class="m">${esc(meta.ilha||"Área mapeada")} · referência ${esc(code)}</div><div class="map-area-ref">A área foi relacionada ao layout desta unidade. Os dados de SCA ainda não estão disponíveis.</div>`};
}
function plantMoveTip(ev){
  const canvas=document.getElementById('plantCanvas'),tip=document.getElementById('plantTip');
  if(!canvas||!tip||!tip.classList.contains('on'))return;
  const r=canvas.getBoundingClientRect(),tw=tip.offsetWidth||390,th=tip.offsetHeight||300;
  let x=ev.clientX-r.left+16,y=ev.clientY-r.top+16;
  if(x+tw>r.width-8)x=ev.clientX-r.left-tw-16;
  if(y+th>r.height-8)y=Math.max(8,r.height-th-8);
  tip.style.left=Math.max(8,x)+'px';tip.style.top=Math.max(8,y)+'px';
}
function plantShow(zone,ev,pin){
  const area=DADOS.areas.find(a=>a.area===zone.dataset.area);
  document.querySelectorAll('#plantOverlay .plant-zone').forEach(z=>z.classList.toggle('active',z===zone));
  const tip=document.getElementById('plantTip'),content=area?plantTooltipHTML(area):(zone.dataset.groupProcess==='1'?plantTooltipProcessStatic(zone.dataset.process,currentUnit):(zone.dataset.groupIsland==='1'?plantTooltipIslandStatic(zone.dataset.island,currentUnit):plantTooltipStatic(zone)));
  plantPinned=!!pin;
  tip.className='plant-tooltip on'+(content.cls==='Crítico'?' crit':content.cls==='Concluído'?' done':content.cls==='Sem dados'?' neutral':'')+(plantPinned?' pinned':'');
  tip.innerHTML=content.html;
  if(ev)plantMoveTip(ev);else{
    const zr=zone.getBoundingClientRect();
    plantMoveTip({clientX:zr.left+zr.width/2,clientY:zr.top+zr.height/2});
  }
}
function plantHide(){
  if(plantPinned)return;
  const tip=document.getElementById('plantTip');if(tip)tip.classList.remove('on');
  document.querySelectorAll('#plantOverlay .plant-zone').forEach(z=>z.classList.remove('active'));
}
function plantZoneCenter(z){
  return z.shape==='rect'?{x:z.x+z.w/2,y:z.y+z.h/2}:{x:z.x,y:z.y};
}
function plantZoneSize(z){
  return z.shape==='rect'?z.w*z.h:Math.PI*z.r*z.r;
}
function plantLabelRepresentatives(zones){
  const byIsland={};
  zones.forEach((z,idx)=>{
    const ref=PLANT_REF[z.area];if(!ref)return;
    (byIsland[ref.island]||=[]).push({z,idx,center:plantZoneCenter(z),size:plantZoneSize(z)});
  });
  const reps={};
  Object.entries(byIsland).forEach(([island,items])=>{
    let chosen;
    if(island==='Estação de Tratamento de Água (ETA)'){
      chosen=items.find(i=>i.z.area==='ETA (Osmose)')||items.find(i=>i.z.area==="Caixa d'água")||null;
    }
    if(!chosen){
      const broad=items.filter(i=>i.z.broad);
      if(broad.length){
        chosen=broad.reduce((best,i)=>!best||i.size>best.size?i:best,null);
      }else{
        chosen=items.reduce((best,i)=>{
          const score=items.reduce((sum,j)=>sum+Math.hypot(i.center.x-j.center.x,i.center.y-j.center.y),0);
          return !best||score<best.score?{...i,score}:best;
        },null);
      }
    }
    reps[island]={idx:chosen.idx,x:chosen.center.x,y:chosen.center.y};
  });
  reps['Geral']={...(reps['Geral']||{}),x:24,y:24};
  reps['Sistema de Combate a Incêndio']={...(reps['Sistema de Combate a Incêndio']||{}),x:956,y:24};
  return reps;
}
function buildUnitIslandGroups(unit){
  const markers=PLANT_UNIT_MARKERS[unit]||[];
  const groups={};
  const markerByArea=Object.fromEntries(markers.map(m=>[m.area,m]));
  const catalog=PLANT_UNIT_AREA_CATALOG[unit]||null;
  const sourceRows=(catalog&&catalog.length)?catalog:markers.map(m=>{const meta=PLANT_AREA_META[m.area]||{};return {area:m.area,code:m.code||meta.cod||'—',island:meta.ilha||'Sem identificação',process:meta.processo||m.area};});
  sourceRows.forEach(row=>{
    const m=markerByArea[row.area]||{x:null,y:null,code:row.code||'—'};
    const island=row.island||'Sem identificação';
    if(!groups[island])groups[island]={island,areas:[],xs:[],ys:[]};
    groups[island].areas.push({area:row.area,process:row.process||row.area,code:row.code||m.code||'—'});
    if(m.x!=null&&m.y!=null){groups[island].xs.push(m.x);groups[island].ys.push(m.y);}
  });
  const manual=PLANT_UNIT_ISLAND_MARKERS[unit]||{};
  Object.values(groups).forEach(g=>{
    if(manual[g.island]){
      g.x=manual[g.island].x;
      g.y=manual[g.island].y;
    }else{
      g.x=g.xs.length?g.xs.reduce((a,b)=>a+b,0)/g.xs.length:500;
      g.y=g.ys.length?g.ys.reduce((a,b)=>a+b,0)/g.ys.length:180;
    }
    g.areas.sort((a,b)=>(a.process||a.area).localeCompare((b.process||b.area),'pt-BR'));
    delete g.xs; delete g.ys;
  });
  if(groups['Geral']&&!manual['Geral']){groups['Geral'].x=24;groups['Geral'].y=24;}
  if(groups['Sistema de Combate a Incêndio']&&!manual['Sistema de Combate a Incêndio']){groups['Sistema de Combate a Incêndio'].x=956;groups['Sistema de Combate a Incêndio'].y=24;}
  return groups;
}
function buildUnitProcessGroups(unit){
  const markers=PLANT_UNIT_MARKERS[unit]||[];
  const markerByArea=Object.fromEntries(markers.map(m=>[m.area,m]));
  const catalog=PLANT_UNIT_AREA_CATALOG[unit]||[];
  const groups={};
  catalog.forEach(row=>{
    const proc=row.process||row.area||'Sem identificação';
    const m=markerByArea[row.area]||{x:null,y:null,code:row.code||'—'};
    if(!groups[proc])groups[proc]={process:proc,island:row.island||'Sem identificação',items:[],xs:[],ys:[]};
    groups[proc].items.push({area:row.area,code:row.code||m.code||'—'});
    if(m.x!=null&&m.y!=null){groups[proc].xs.push(m.x);groups[proc].ys.push(m.y);}
  });
  Object.values(groups).forEach(g=>{
    g.x=g.xs.length?g.xs.reduce((a,b)=>a+b,0)/g.xs.length:500;
    g.y=g.ys.length?g.ys.reduce((a,b)=>a+b,0)/g.ys.length:180;
    g.items.sort((a,b)=>(a.area||'').localeCompare((b.area||''),'pt-BR'));
    delete g.xs; delete g.ys;
  });
  return groups;
}
function plantTooltipIslandStatic(island, unit){
  const groups=buildUnitIslandGroups(unit); const g=groups[island];
  if(!g)return {cls:'Sem dados',html:`<div class="tag">Sem dados</div><h4>${esc(island||'Ilha')}</h4><div class="m">Sem áreas mapeadas.</div>`};
  const body=g.areas.map(a=>`<div class="map-group"><div class="map-group-title"><span>${esc(a.process||a.area)}</span><span>${esc(a.code)}</span></div><ul><li><span class="sdot" style="background:#94A3B8"></span><span><b>Área:</b> ${esc(a.area)} · SCAs ainda não disponíveis para esta unidade.</span></li></ul></div>`).join('');
  return {cls:'Sem dados',html:`<div class="tag">Sem dados</div><h4>${esc(g.island)}</h4><div class="m">${g.areas.length} processo${g.areas.length===1?'':'s'} mapeado${g.areas.length===1?'':'s'} nesta ilha.</div>${body}`};
}
function plantTooltipProcessStatic(processName, unit){
  const groups=buildUnitProcessGroups(unit); const g=groups[processName];
  if(!g)return {cls:'Sem dados',html:`<div class="tag">Sem dados</div><h4>${esc(processName||'Processo')}</h4><div class="m">Sem áreas mapeadas.</div>`};
  const body=g.items.map(a=>`<div class="map-group"><div class="map-group-title"><span>${esc(a.area)}</span><span>${esc(a.code)}</span></div><ul><li><span class="sdot" style="background:#94A3B8"></span><span>SCAs ainda não disponíveis para esta unidade.</span></li></ul></div>`).join('');
  return {cls:'Sem dados',html:`<div class="tag">Sem dados</div><h4>${esc(g.process)}</h4><div class="m">Ilha: ${esc(g.island)} · ${g.items.length} área${g.items.length===1?'':'s'} mapeada${g.items.length===1?'':'s'}.</div>${body}`};
}
function bindPlantZones(){
  const svg=document.getElementById('plantOverlay');
  svg.querySelectorAll('.plant-zone').forEach(zone=>{
    zone.addEventListener('mouseenter',ev=>{if(!plantPinned)plantShow(zone,ev,false);});
    zone.addEventListener('mousemove',ev=>{if(!plantPinned)plantMoveTip(ev);});
    zone.addEventListener('mouseleave',plantHide);
    zone.addEventListener('focus',()=>plantShow(zone,null,false));
    zone.addEventListener('blur',plantHide);
    zone.addEventListener('click',ev=>{ev.stopPropagation();plantShow(zone,ev,!plantPinned||!zone.classList.contains('active'));});
  });
  const canvas=document.getElementById('plantCanvas');
  canvas.onclick=ev=>{if(ev.target.closest('.plant-zone')||ev.target.closest('.plant-tooltip'))return;plantPinned=false;plantHide();};
  const tip=document.getElementById('plantTip');
  tip.onclick=ev=>ev.stopPropagation();
  tip.onmousedown=ev=>ev.stopPropagation();
  tip.onwheel=ev=>ev.stopPropagation();
}
function renderPlant(){
  const svg=document.getElementById('plantOverlay');if(!svg)return;
  const scroll=document.querySelector('#page3 .plant-scroll');
  const shell=document.querySelector('#page3 .plant-shell');
  const img=document.querySelector('#plantCanvas .plant-base');
  const intro=document.querySelector('#page3 .plant-intro > span');
  const legend=document.querySelector('#page3 .plant-legend');
  const cfg=PLANT_BASES[currentUnit];
  let empty=document.getElementById('plantEmptyState');
  if(!empty&&shell){empty=document.createElement('div');empty.id='plantEmptyState';empty.className='plant-empty-state';empty.textContent='A planta ainda não foi disponibilizada para esta unidade.';shell.appendChild(empty);}
  if(!cfg){svg.innerHTML='';if(scroll)scroll.style.display='none';if(empty)empty.style.display='block';return;}
  if(scroll)scroll.style.display='';if(empty)empty.style.display='none';
  if(img){if(img.src!==cfg.src)img.src=cfg.src;img.alt=cfg.alt;}
  svg.setAttribute('viewBox',`0 0 1000 ${cfg.vh||367}`);
  plantPinned=false;const tip=document.getElementById('plantTip');if(tip)tip.className='plant-tooltip';
  if(currentUnit==='rio-verde'){
    if(intro)intro.textContent='Passe o mouse sobre as áreas destacadas para consultar a ilha de processo e os respectivos itens do checklist.';
    if(legend)legend.innerHTML='<span><i style="background:var(--green)"></i>Concluída</span><span><i style="background:var(--blue)"></i>Em andamento</span><span><i style="background:var(--red)"></i>Não iniciada</span>';
    const areaByName=Object.fromEntries(DADOS.areas.map(a=>[a.area,a]));
    const zones=[...PLANT_ZONES].filter(z=>areaByName[z.area]).sort((a,b)=>(b.broad?0:1)-(a.broad?0:1));
    const representatives=plantLabelRepresentatives(zones);
    svg.innerHTML=Object.entries(representatives).map(([island,rep])=>{
      const z=zones[rep.idx],a=z?areaByName[z.area]:null;if(!z||!a)return'';
      const col=plantZoneColor(a),ref=PLANT_REF[z.area]||{};
      return `<g class="plant-zone" data-area="${esc(z.area)}" data-island="${esc(island)}" data-code="${esc(ref.code||'—')}" tabindex="0" style="--zone:${col}"><title>${esc(z.area)}</title><circle class="zone-label-bg" cx="${rep.x}" cy="${rep.y}" r="9"></circle><rect class="zone-symbol" x="${rep.x-3}" y="${rep.y-3}" width="6" height="6" rx="1"></rect></g>`;
    }).join('');
  }else if(currentUnit==='nova-mutum'){
    if(intro)intro.textContent='Passe o mouse sobre os símbolos para consultar cada ilha de processo. Os processos e áreas mapeadas aparecem na tooltip; os dados de SCAs ainda não estão disponíveis para esta unidade.';
    if(legend)legend.innerHTML='<span><i style="background:#64748B"></i>Ilha de processo mapeada - sem dados de status</span>';
    const groups=buildUnitIslandGroups('nova-mutum');
    svg.innerHTML=Object.values(groups).map(g=>{
      const my=((g.y)*(cfg.vh||367)/367);
      return `<g class="plant-zone plant-zone-empty" data-group-island="1" data-area="${esc(g.areas[0]?.area||g.island)}" data-island="${esc(g.island)}" data-code="${esc(g.areas[0]?.code||'—')}" tabindex="0" style="--zone:#64748B"><title>${esc(g.island)}</title><circle class="zone-label-bg" cx="${g.x}" cy="${my}" r="8"></circle><rect class="zone-symbol" x="${g.x-2.7}" y="${my-2.7}" width="5.4" height="5.4" rx="1"></rect></g>`;
    }).join('');
  }else if(currentUnit==='rondonopolis'){
    if(intro)intro.textContent='Passe o mouse sobre os símbolos para consultar cada processo mapeado na planta. A tooltip apresenta a ilha de processo e as áreas correspondentes; os dados de SCAs ainda não estão disponíveis para esta unidade.';
    if(legend)legend.innerHTML='<span><i style="background:#64748B"></i>Processo mapeado - sem dados de status</span>';
    const groups=buildUnitProcessGroups('rondonopolis');
    svg.innerHTML=Object.values(groups).map(g=>{
      const gx=((((g.x/1000*7796)-80)/5220*1000)-210)+(RND_PROCESS_X_OFFSETS[g.process]||0);
      const gy=(((g.y/367*4967)-730)/3870*(cfg.vh||367))+(RND_PROCESS_Y_OFFSETS[g.process]||0);
      return `<g class="plant-zone plant-zone-empty" data-group-process="1" data-process="${esc(g.process)}" data-area="${esc(g.items[0]?.area||g.process)}" data-island="${esc(g.island)}" data-code="${esc(g.items[0]?.code||'—')}" tabindex="0" style="--zone:#64748B"><title>${esc(g.process)}</title><circle class="zone-label-bg" cx="${gx}" cy="${gy}" r="8"></circle><rect class="zone-symbol" x="${gx-2.7}" y="${gy-2.7}" width="5.4" height="5.4" rx="1"></rect></g>`;
    }).join('');
  }else{
    if(intro)intro.textContent='Passe o mouse sobre os símbolos para consultar as áreas relacionadas ao layout. Os dados de SCA ainda não estão disponíveis para esta unidade.';
    if(legend)legend.innerHTML='<span><i style="background:#64748B"></i>Área mapeada - sem dados de status</span>';
    const markers=PLANT_UNIT_MARKERS[currentUnit]||[];
    svg.innerHTML=markers.map(m=>{
      const meta=PLANT_AREA_META[m.area]||{};
      return `<g class="plant-zone plant-zone-empty" data-area="${esc(m.area)}" data-island="${esc(meta.ilha||'—')}" data-code="${esc(m.code||'—')}" tabindex="0" style="--zone:#64748B"><title>${esc(m.area)}</title><circle class="zone-label-bg" cx="${m.x}" cy="${m.y}" r="8"></circle><rect class="zone-symbol" x="${m.x-2.7}" y="${m.y-2.7}" width="5.4" height="5.4" rx="1"></rect></g>`;
    }).join('');
  }
  bindPlantZones();
}

function openExportDialog(){
  const modal=document.getElementById('exportModal');
  const error=document.getElementById('exportError');
  const unit=document.getElementById('exportUnitSelect');
  if(unit)unit.value=currentUnit;
  if(error)error.textContent='';
  if(modal){modal.classList.add('on');document.body.style.overflow='hidden';}
}
function closeExportDialog(){
  const modal=document.getElementById('exportModal');
  if(modal)modal.classList.remove('on');
  document.body.style.overflow='';
}
function clearPrintSelection(){
  document.querySelectorAll('.page').forEach(page=>page.classList.remove('print-included','print-excluded','print-first'));
  document.body.classList.remove('print-selection-active');
}
async function prepareImagesForPrint(selected){
  const images=selected.flatMap(id=>[...document.querySelectorAll(`#${id} img`)]);
  if(!images.length)return;
  images.forEach(img=>{
    img.loading='eager';
    img.decoding='sync';
    try{img.fetchPriority='high';}catch(e){}
  });
  const waitForImage=img=>new Promise(resolve=>{
    const finish=()=>{
      if(typeof img.decode==='function'){img.decode().catch(()=>{}).finally(resolve);}
      else resolve();
    };
    if(img.complete&&img.naturalWidth>0){finish();return;}
    const preload=new Image();
    preload.onload=()=>finish();
    preload.onerror=()=>resolve();
    preload.src=img.currentSrc||img.src;
  });
  await Promise.race([
    Promise.all(images.map(waitForImage)),
    new Promise(resolve=>setTimeout(resolve,15000))
  ]);
}
async function printSelectedPages(){
  const selected=[...document.querySelectorAll('input[name="exportPage"]:checked')].map(input=>input.value);
  const unitToPrint=document.getElementById('exportUnitSelect')?.value||currentUnit;
  const error=document.getElementById('exportError');
  if(!selected.length){
    if(error)error.textContent='Selecione pelo menos uma aba para exportar.';
    return;
  }
  if(error)error.textContent='';
  if(unitToPrint!==currentUnit)setUnit(unitToPrint);
  clearPrintSelection();
  document.querySelectorAll('.page').forEach(page=>{
    page.classList.add(selected.includes(page.id)?'print-included':'print-excluded');
  });
  const first=document.getElementById(selected[0]);
  if(first)first.classList.add('print-first');
  document.body.classList.add('print-selection-active');
  closeExportDialog();
  await prepareImagesForPrint(selected);
  await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));
  document.title=PDF_EXPORT_NAMES[unitToPrint]||ORIGINAL_DOCUMENT_TITLE;
  window.print();
}
window.addEventListener('afterprint',()=>{clearPrintSelection();document.title=ORIGINAL_DOCUMENT_TITLE;});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape')closeExportDialog();});
document.getElementById('exportModal')?.addEventListener('click',ev=>{if(ev.target.id==='exportModal')closeExportDialog();});


function docNormStatus(v){return String(v||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().trim();}
function docIsDone(v){const s=docNormStatus(v);return s.includes("finalizado")||s.includes("entregue")||s.includes("concluido");}
function renderDocuments(){
  const page=document.getElementById("page4");if(!page)return;
  const cfg=UNIT_DATA[currentUnit].documents,rows=cfg.rows||[];
  const done=rows.filter(r=>docIsDone(r.status)).length,pending=rows.length-done;
  const groups={};
  rows.forEach(r=>{const key=r.area||"Não informado";const g=groups[key]||(groups[key]={total:0,done:0});g.total++;if(docIsDone(r.status))g.done++;});
  const areaCards=Object.entries(groups).sort((a,b)=>a[0].localeCompare(b[0],"pt-BR")).map(([name,g])=>{
    const pend=g.total-g.done,p=Math.round(100*g.done/g.total);
    return `<div class="docs-area-card"><div><h4>${esc(name)}</h4><p>${g.total} documento${g.total===1?"":"s"} no total</p></div>
      <div class="docs-area-viz"><div class="docs-donut" style="--done:${(100*g.done/g.total).toFixed(2)}" aria-label="${p}% dos documentos entregues">
        <div class="docs-donut-center"><strong>${p}%</strong><span>entregues</span></div></div>
        <div class="docs-area-legend"><span><i style="background:var(--green)"></i><span><b>${g.done}</b> ${esc(cfg.doneLabel||"Entregues")}</span></span>
        <span><i style="background:var(--red)"></i><span><b>${pend}</b> Pendentes</span></span></div></div></div>`;
  }).join("")||`<div class="docs-empty-state">Nenhum documento foi carregado para esta unidade.</div>`;
  const body=rows.map(r=>`<tr><td>${esc(r.description||"—")}</td><td>${esc(r.area||"—")}</td><td>${esc(r.manager||"—")}</td>
    <td><span class="doc-status ${docIsDone(r.status)?"entregue":"pendente"}">${esc(r.status||"—")}</span></td><td>${esc(r.comments||"—")}</td></tr>`).join("");
  page.innerHTML=`
    <div class="section-h"><div class="badge">4</div><h2>Entrega de Documentos</h2><span class="hint">Base: ${esc(cfg.source)}</span></div>
    <div class="docs-kpis">
      <div class="docs-kpi"><div class="label">Quantidade de documentos</div><div class="value">${rows.length}</div></div>
      <div class="docs-kpi deadline"><div class="label">Prazo único</div><div class="value">${esc(cfg.deadline||"—")}</div></div>
      <div class="docs-kpi done"><div class="label">Quantidade de itens entregues</div><div class="value">${done}</div></div>
      <div class="docs-kpi pending"><div class="label">Quantidade de itens pendentes</div><div class="value">${pending}</div></div>
    </div>
    <div class="section-h compact-section"><div class="badge">·</div><h2>Itens pendentes por área</h2></div>
    <div class="docs-area-grid">${areaCards}</div>
    <div class="docs-filter-section">
      <div class="section-h compact-section"><div class="badge">·</div><h2>Relação completa de documentos</h2><span class="hint">Filtros aplicados à tabela abaixo.</span></div>
      <div class="selbar docs-filterbar" id="docsFilterbar">
        <input id="docsSearch" type="search" placeholder="Buscar documento ou comentário">
        <select id="docsAreaFilter"><option value="">${esc(cfg.filterLabels.area)}</option></select>
        <select id="docsStatusFilter"><option value="">Todos os status</option></select>
        <select id="docsManagerFilter"><option value="">${esc(cfg.filterLabels.manager)}</option></select>
        <button type="button" class="docs-filter-clear" id="docsFilterClear">Limpar filtros</button>
        <span class="docs-filter-count" id="docsFilterCount">${rows.length} de ${rows.length} registros</span>
      </div>
    </div>
    <div class="docs-table-card"><div class="docs-table-head"><span id="docsTableCount">${rows.length} registro${rows.length===1?"":"s"}</span></div>
      <div class="docs-table-wrap"><table class="docs-table"><thead><tr>
        <th class="col-desc">Documento</th><th class="col-area">${esc(cfg.columns.area)}</th><th class="col-manager">${esc(cfg.columns.manager)}</th>
        <th class="col-status">Status</th><th class="col-comments">${esc(cfg.columns.comments)}</th>
      </tr></thead><tbody>${body}</tbody></table></div></div>`;
  initDocumentFilters();
}

function docsNorm(v){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();}
function initDocumentFilters(){
  const table=document.querySelector('#page4 .docs-table');
  if(!table)return;
  const rows=[...table.tBodies[0].rows];
  const areaSel=document.getElementById('docsAreaFilter');
  const statusSel=document.getElementById('docsStatusFilter');
  const managerSel=document.getElementById('docsManagerFilter');
  const search=document.getElementById('docsSearch');
  const clear=document.getElementById('docsFilterClear');
  const uniqValues=idx=>[...new Set(rows.map(r=>r.cells[idx]?.textContent.trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'pt-BR'));
  const fill=(sel,values)=>values.forEach(v=>sel.insertAdjacentHTML('beforeend',`<option value="${esc(v)}">${esc(v)}</option>`));
  fill(areaSel,uniqValues(1));
  fill(managerSel,uniqValues(2));
  fill(statusSel,uniqValues(3));
  const apply=()=>{
    const q=docsNorm(search.value),area=docsNorm(areaSel.value),status=docsNorm(statusSel.value),manager=docsNorm(managerSel.value);
    let visible=0;
    rows.forEach(r=>{
      const doc=docsNorm(r.cells[0]?.textContent),rowArea=docsNorm(r.cells[1]?.textContent),rowManager=docsNorm(r.cells[2]?.textContent),rowStatus=docsNorm(r.cells[3]?.textContent),comments=docsNorm(r.cells[4]?.textContent);
      const show=(!q||doc.includes(q)||comments.includes(q))&&(!area||rowArea===area)&&(!status||rowStatus===status)&&(!manager||rowManager===manager);
      r.style.display=show?'':'none';
      if(show)visible++;
    });
    document.getElementById('docsFilterCount').textContent=`${visible} de ${rows.length} registros`;
    document.getElementById('docsTableCount').textContent=`${visible} registro${visible===1?'':'s'}`;
  };
  [search,areaSel,statusSel,managerSel].forEach(el=>el.addEventListener(el===search?'input':'change',apply));
  clear.addEventListener('click',()=>{search.value='';areaSel.value='';statusSel.value='';managerSel.value='';apply();search.focus();});
  apply();
}


function setUnit(unitKey){
  if(!UNIT_DATA[unitKey])return;
  currentUnit=unitKey;
  DADOS=UNIT_DATA[currentUnit].operational;
  VISTORIA=parseUnitDate(DADOS.meta.vistoria);
  sortK="n";sortDir=-1;macroFilterReady=false;
  detFilter="all";selIlha="";selDisc="";selSup="";selGer="";selCrit="";
  const qEl=document.getElementById("q"),stEl=document.getElementById("fStatus"),macroEl=document.getElementById("fMacro");
  if(qEl)qEl.value="";
  if(stEl)stEl.value="";
  if(macroEl){macroEl.value="";macroEl.innerHTML='<option value="">Todos os SCA</option>';}
  const headerSel=document.getElementById("unitSelect"),exportSel=document.getElementById("exportUnitSelect");
  if(headerSel)headerSel.value=currentUnit;
  if(exportSel)exportSel.value=currentUnit;
  renderAll();
}

document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));t.classList.add('active');document.getElementById(t.dataset.page).classList.add('active');window.scrollTo({top:0,behavior:'smooth'});});
document.getElementById('unitSelect').onchange=ev=>setUnit(ev.target.value);
document.getElementById('q').oninput=renderTable;
document.getElementById('fStatus').onchange=renderTable;
document.getElementById('fMacro').onchange=renderTable;
document.querySelectorAll('#tbl thead th.sortable').forEach(th=>th.onclick=()=>{const k=th.dataset.k;if(sortK===k)sortDir*=-1;else{sortK=k;sortDir=1;}renderTable();});

function renderAll(){renderMast();renderExec();renderFase();renderReprog();renderHeat();renderKPIs();renderDisc();renderGer();renderCriteria();renderCriteriaSCA();renderTable();renderDetFilters();renderDetail();renderPlant();renderDocuments();}
